  ('90000001-0000-4000-8000-000000000002', '30000001-0000-4000-8000-000000000001', 'เธญเธฐเนเธซเธฅเนเนเธเธฅเนเธซเธกเธ” 5 เธฃเธฒเธขเธเธฒเธฃ',       'เนเธชเนเธเธฃเธญเธเธเนเธณเธกเธฑเธเน€เธเธฃเธทเนเธญเธ M35 เน€เธซเธฅเธทเธญ 3 เธเธดเนเธ, เธเนเธฒเน€เธเธฃเธเธซเธเนเธฒ M35 เน€เธซเธฅเธทเธญ 5 เธเธดเนเธ, เธชเธฒเธขเธเธฒเธเนเธ—เธกเนเธกเธดเนเธ เน€เธซเธฅเธทเธญ 2 เน€เธชเนเธ, เนเธเธ•เน€เธ•เธญเธฃเธตเน 12V เน€เธซเธฅเธทเธญ 4 เธฅเธนเธ, เธซเธกเนเธญเธเนเธณ M35 เน€เธซเธฅเธทเธญ 2 เธเธดเนเธ', 'warning', now() - interval '2 hours'),
  ('90000001-0000-4000-8000-000000000003', '30000001-0000-4000-8000-000000000006', 'เธเธฒเธเธเนเธญเธกเน€เธชเธฃเนเธ WO-2026-004',    'เนเธเธเธฒเธเธเนเธญเธก WO-2026-004 (เน€เธเธฃเธ เธเธฅ-0021) เน€เธชเธฃเนเธเธชเธดเนเธ เธเนเธฒเนเธเนเธเนเธฒเธข 17,800 เธเธฒเธ—',    'success', now() - interval '3 hours'),
  ('90000001-0000-4000-8000-000000000004', '30000001-0000-4000-8000-000000000006', 'เธญเธฐเนเธซเธฅเนเธฃเธญเธ WO-2026-003',        'เนเธเธเธฒเธ WO-2026-003 เธฃเธญเธญเธฐเนเธซเธฅเน เธเธฅเธฑเธ—เธเนKIT M35 เธขเธฑเธเนเธกเนเธกเธตเนเธเธเธฅเธฑเธ',               'warning', now() - interval '5 hours'),
  ('90000001-0000-4000-8000-000000000005', '30000001-0000-4000-8000-000000000006', 'เนเธเธเธเนเธญเธกเน€เธเธดเธเธเธณเธซเธเธ” 8 เธฃเธฒเธขเธเธฒเธฃ',    'เธกเธตเนเธเธเธเนเธญเธกเธเธณเธฃเธธเธเน€เธเธดเธเธเธณเธซเธเธ” 8 เธฃเธฒเธขเธเธฒเธฃ เธเธฃเธธเธ“เธฒเธเธฑเธ”เธชเธฃเธฃเธเนเธฒเธเน€เธฃเนเธเธ”เธณเน€เธเธดเธเธเธฒเธฃ',           'error',   now() - interval '1 day'),
  ('90000001-0000-4000-8000-000000000006', '30000001-0000-4000-8000-000000000004', 'เนเธเนเธเธเนเธญเธกเนเธซเธกเน RR-2026-011',     'เธเธฅ-0044 เธเนเธฒเน€เธเธฃเธเธชเธถเธเธซเธฃเธญ เนเธ”เนเธขเธดเธเน€เธชเธตเธขเธเน€เธญเธตเนเธขเธ” เธ•เนเธญเธเน€เธเธฅเธตเนเธขเธเธเนเธฒเน€เธเธฃเธ',              'info',    now() - interval '6 hours'),
  ('90000001-0000-4000-8000-000000000007', '30000001-0000-4000-8000-000000000006', 'เธเธฒเธเธเนเธญเธกเน€เธชเธฃเนเธ WO-2026-007',    'เนเธเธเธฒเธเธเนเธญเธก WO-2026-007 (เนเธ”เธชเธ•เธฒเธฃเนเธ— M50-006) เน€เธชเธฃเนเธเธชเธดเนเธ เธเนเธฒเนเธเนเธเนเธฒเธข 11,000 เธเธฒเธ—',  'success', now() - interval '2 days'),
  ('90000001-0000-4000-8000-000000000008', '30000001-0000-4000-8000-000000000004', 'เธฃเธ–เธเนเธฒเธเธเนเธญเธก 6 เธเธฑเธ',             'เธเธ“เธฐเธเธตเนเธกเธตเธขเธฒเธเธเธฒเธซเธเธฐเธเนเธฒเธเธเนเธญเธก 6 เธเธฑเธ: IN_REPAIR 4 เธเธฑเธ, WAITING_PARTS 2 เธเธฑเธ',     'warning', now() - interval '3 days'),
  ('90000001-0000-4000-8000-000000000009', '30000001-0000-4000-8000-000000000006', 'เธเธฒเธเธเนเธญเธกเน€เธชเธฃเนเธ WO-2026-010',    'เนเธเธเธฒเธเธเนเธญเธก WO-2026-010 (เธเนเธฒเน€เธเธฃเธ M718-002) เน€เธชเธฃเนเธเธชเธดเนเธ เธเนเธฒเนเธเนเธเนเธฒเธข 4,200 เธเธฒเธ—',   'success', now() - interval '4 days'),
  ('90000001-0000-4000-8000-000000000010', '30000001-0000-4000-8000-000000000001', 'เธชเธฃเธธเธเธฃเธฒเธขเธชเธฑเธเธ”เธฒเธซเน',               'เธชเธฑเธเธ”เธฒเธซเนเธเธตเน: เธเนเธญเธกเน€เธชเธฃเนเธ 3 เธเธฑเธ เธเนเธฒเธเธเนเธญเธก 6 เธเธฑเธ เธญเธฐเนเธซเธฅเนเนเธเธฅเนเธซเธกเธ” 5 เธฃเธฒเธขเธเธฒเธฃ เธเธฃเธฐเธชเธดเธ—เธเธดเธ เธฒเธ 75%', 'info',    now() - interval '7 days');
