  ('50000001-0000-4000-8000-000000000001', 'เธเธฅ-0001', 'REO-M35-001', '2015-06-15', 'เธเธญเธเธเธฑเธเธ—เธซเธฒเธฃเธฃเธฒเธเธ—เธตเน 1', 'เธฃเนเธญเธขเน€เธญเธ เธงเธดเน€เธเธตเธขเธฃ เน€เธซเธฅเธทเธญเธเธฒเธก', '7800', '130', 1, 'เธ•เธฃเธงเธเธชเธ เธฒเธเธเนเธญเธเธฃเธฑเธเธกเธญเธ เน€เธเธฅเธตเนเธขเธเธเนเธณเธกเธฑเธเน€เธเธฃเธทเนเธญเธ เนเธชเนเธเธฃเธญเธเธญเธฒเธเธฒเธจเนเธซเธกเน', '30000001-0000-4000-8000-000000000001'),
  ('50000001-0000-4000-8000-000000000004', 'เธเธฅ-0004', 'REO-M35-004', '2016-03-20', 'เธเธฃเธกเธ—เธซเธฒเธฃเธฃเธฒเธเธ—เธตเน 1', 'เธชเธดเธเน€เธญเธ เธชเธกเธจเธฑเธเธ”เธดเน เธฃเธฑเธเธเธฒเธ•เธด', '7800', '130', 1, 'เน€เธเธฅเธตเนเธขเธเธเธฅเธฑเธ—เธเนKIT เธเนเธฒเน€เธเธฃเธเธซเธเนเธฒเธซเธฅเธฑเธ เธ•เธฃเธงเธเธฃเธฐเธเธเนเธเธเนเธฒ', '30000001-0000-4000-8000-000000000001'),
  ('50000001-0000-4000-8000-000000000013', 'เธเธฅ-0013', 'KIA-FTS-001', '2018-09-10', 'เธเธญเธเธฃเนเธญเธขเธเนเธญเธกเธเธณเธฃเธธเธ', 'เธเนเธฒเธชเธดเธเธ•เธฃเธต เธชเธกเธเธฒเธข เธเธฅเนเธฒเธซเธฒเธ', '6900', '160', 1, 'เธ•เธฃเธงเธเน€เธเนเธเธชเธ เธฒเธเธ—เธฑเนเธงเนเธ เธ—เธธเธเธฃเธฐเธเธเธเธเธ•เธด', '30000001-0000-4000-8000-000000000001'),
  ('50000001-0000-4000-8000-000000000022', 'เธเธฅ-0022', 'KAISER-M50-001', '1968-12-01', 'เธซเธเนเธงเธขเธ—เธซเธฒเธฃเธชเธฃเธฃเธเธฒเธงเธธเธ', 'เธเธฑเธเธ•เธฃเธต เธชเธกเธเธฒเธข เนเธเธ”เธต', '5200', '110', 1, 'เธ•เนเธเนเธเธ M50 เธ•เธฃเธงเธเน€เธเธฃเธทเนเธญเธเธขเธเธ•เน เธฃเธฐเธเธเธฃเธฐเธเธฒเธขเธเธงเธฒเธกเธฃเนเธญเธ เธฃเธฐเธเธเนเธเธเนเธฒ', '30000001-0000-4000-8000-000000000001'),
  ('50000001-0000-4000-8000-000000000042', 'เธเธฅ-0042', 'CHK-COLORADO-001', '2022-01-15', 'เธเธฃเธกเธ—เธซเธฒเธฃเธฃเธฒเธเธ—เธตเน 1', 'เธชเธดเธเธ•เธฃเธต เธ“เธฃเธเธเน เน€เธเนเธกเนเธเนเธ', '2500', '163', 1, 'เธเธฃเธฐเธเธฐ Chevrolet Colorado เธ•เธฃเธงเธเธชเธ เธฒเธเธ—เธฑเนเธงเนเธเธเนเธญเธเนเธเนเธเธฒเธ', '30000001-0000-4000-8000-000000000001'),
  ('50000001-0000-4000-8000-000000000045', 'เธเธฅ-0045', 'FORD-M718-001', '1972-04-10', 'เธซเธเนเธงเธขเนเธเธ—เธขเนเธ—เธซเธฒเธฃ', 'เธเนเธฒเธชเธดเธเนเธ— เธกเธฒเธเธ เธ—เธฃเธเธเธฅ', '3900', '110', 1, 'เธฃเธ–เธเธขเธฒเธเธฒเธฅ M718 เธ•เธฃเธงเธเธฃเธฐเธเธเธเธธเธเน€เธเธดเธ เธญเธธเธเธเธฃเธ“เนเนเธเธ—เธขเนเธเธฃเธ', '30000001-0000-4000-8000-000000000001'),
  ('50000001-0000-4000-8000-000000000020', 'เธเธฅ-0020', 'DAEWOO-BUS-001', '2017-08-20', 'เธเธญเธเธเธฑเธเธ—เธซเธฒเธฃเธฃเธฒเธเธ—เธตเน 2', 'เธชเธดเธเนเธ— เนเธเธจเธฒเธฅ เธเธฅเธฑเธเธ—เธฃเธฑเธเธขเน', '6900', '240', 1, 'เธฃเธ–เธเธฑเธช Daewoo เธ•เธฃเธงเธเน€เธเธฃเธทเนเธญเธเธขเธเธ•เน เธฃเธฐเธเธเนเธญเธฃเน เธฃเธฐเธเธเนเธเธเนเธฒ', '30000001-0000-4000-8000-000000000001'),
  ('50000001-0000-4000-8000-000000000039', 'เธเธฅ-0039', 'KAISER-M50R-001', '1968-05-15', 'เธซเธเนเธงเธขเธ—เธซเธฒเธฃเธชเธฃเธฃเธเธฒเธงเธธเธ', 'เธเนเธฒเธชเธดเธเน€เธญเธ เธชเธกเธเธนเธฃเธ“เน เธกเธตเธเธตเธกเธทเธญ', '5200', '110', 1, 'M50 เธเธฃเธฑเธเธเธฃเธธเธเนเธซเธกเน เธ•เธฃเธงเธเน€เธเธฃเธทเนเธญเธเธขเธเธ•เน เน€เธเธฅเธตเนเธขเธเธเนเธงเธเธฅเนเธฒเธเธ—เธฑเนเธเธเธธเธ”', '30000001-0000-4000-8000-000000000001');
